function [x, N, res1, res2] = Newton(f, dfdx, x0, tol1, tol2, MaxIt)% Computes a zero of function fun with the Newton method%% INPUTS:% f  = function handle% dfdx  = the derivative of f% x0   = the starting point% tol1  = the absolute precision on the solution |f(x_k)|% tol2  = the absolute precision on the iterative error |x_{k+1}-x_k|% MaxIt = the max number of iterations% OUTPUTS:% x  = the result% res1 = the estimated absolute error |f(x_k)|% res2 = the iterative error |x_{k+1}-x_k|% N = the number of iterations% DEFAULTS:% tol1 = tol2  = 1e-4% nmax = 100if nargin < 3    error('A function and a starting point are needed')endif nargin < 4    tol1 = 1e-4;endif nargin < 5    tol2 = 1e-4;endif nargin < 6    MaxIt = 100;endx   = x0;fx  = f(x);dfx = dfdx(x);if ((imag(fx) ~= 0) + (~isfinite(fx))) > 0    error('Function is not defined in x0')end%imag(fx) ~= 0 verifica si fx tiene una parte imaginaria diferente de cero %(resultado no es un valor real)%~isfinite(fx) comprueba si fx no es un nœmero finito, lo que incluye NaN %(Not a Number), Inf y -Inf Cualquiera de estos valores sugiere que la %funci—n no est‡ bien definida o no produce un resultado v‡lido en x0.if (~isfinite(dfx)) > 0    error('Function appears not to be differentiable at x0')elseif abs(dfx) < 2*eps*abs(fx)    error('The derivative at x0 is too small to start the iteration')endN = 1;res1(1)  = abs(fx);res2(1)  = abs(fx/dfx);while res1(N) >= tol1 && res2(N) >= tol2 && N < MaxIt    N = N + 1; % Incrementa el contador de iteraciones    delta = -fx/dfx; % Calcula el cambio en x    x = x + delta; % Actualiza el valor de x    fx = f(x); % Evalœa la funci—n en el nuevo punto x    dfx = dfdx(x); % Evalœa la derivada de la funci—n en el nuevo punto x        if ((imag(fx) ~= 0) + (~isfinite(fx))) > 0        warning('Iteration pointed outside the domain')        break;    end	    if abs(dfx) < 2*eps*abs(fx)        warning('Iteration reached a point with a too small derivative')        break;    end    res1(N) = abs(fx); % Actualiza res1 con el nuevo error absoluto de fx    res2(N) = abs(delta); % Actualiza res2 con el valor absoluto del cambio en xendif ( N == MaxIt && res2(N) > tol2 )   fprintf (' No solution with accuracy %d has been encountered with %d iterations', tol1, N);endclffigure(1)subplot(1,2,1)fplot(f,'b','DisplayName','f(x)')xlabel('x')ylabel('y')hold onfplot(dfdx,'r','DisplayName','df/dx(x)')title('df/dx(x)')grid onlegend showsubplot(1,2,2)plot(res1(1:N), 'r-o','DisplayName','Error')title('Error vs. Iteraciones')xlabel('Nœmero de Iteraciones')hold onplot(log(res1(1:N)), 'b-o','DisplayName','log(Error)')grid onlegend showend